<script setup lang="ts">import {computed} from "vue";import type {GraphNode} from "@/types/graph";import type {ToolCall} from "@/types/toolCall";const props=defineProps<{node?:GraphNode;toolCall?:ToolCall}>();const title=computed(()=>props.node?.type==="user_intent"?"对话意图":props.node?.type==="sensitive_object"?"发现敏感对象":props.node?.type==="blocked"?"执行已阻止":"执行前决策");const decision=computed(()=>props.node?.decision??props.toolCall?.decision??"review");const decisionLabel=computed(()=>({block:"阻止",allow:"允许",review:"复核"} as const)[decision.value]);</script>
<template><div v-if="node" class="tab-copy"><span class="decision-badge" :class="decision">{{decisionLabel}}</span><h3>{{title}}</h3><p>{{node.detail}}</p><dl><div><dt>节点类型</dt><dd>{{node.type}}</dd></div><div><dt>风险等级</dt><dd>{{node.risk}}</dd></div><div><dt>命中规则</dt><dd>{{node.policyId ?? toolCall?.policyHits.join(', ') ?? '上下文评估'}}</dd></div><div v-if="toolCall"><dt>工具耗时</dt><dd>{{toolCall.latencyMs}}ms</dd></div></dl></div><div v-else class="empty">请选择一个路径节点查看决策详情。</div></template>
<style scoped>
.decision-badge { display:inline-flex; padding:5px 8px; border-radius:7px; color:#fff; background:#c18318; font:700 9px var(--trace-font-mono); letter-spacing:.08em;text-transform:uppercase }.decision-badge.block{background:var(--trace-red)}.decision-badge.allow{background:var(--trace-success)}.tab-copy h3 { margin:12px 0 7px; font-size:14px; }.tab-copy p { margin:0; color:#6e7989; font-size:11px; line-height:1.7; }dl { margin:18px 0 0; }dl div { display:flex; justify-content:space-between; gap:14px; padding:9px 0; border-bottom:1px solid #edf0f2; font-size:10px; }dt { color:#8a94a2; } dd { max-width:60%;margin:0; overflow-wrap:anywhere;text-align:right; font-family:var(--trace-font-mono); }.empty{color:#8993a1;font-size:10px}
</style>
